CREATE DEFINER=`natalia.carrasco`@`%` FUNCTION `fn_nombre_prueba`(p_num INT) RETURNS varchar(150) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
    RETURN ELT(
        1 + MOD(p_num, 10),
        'James', 'Emily', 'Michael', 'Olivia',
        'Daniel', 'Sophia', 'William', 'Emma',
        'Alexander', 'Charlotte'
    );
END ;;
